{
  "name": "agent-comic",
  "version": "0.6.0",
  "description": "A little comic above the prompt: Claude acts out what the agent is doing in animated pixel scenes, from a home hub with keepsakes",
  "author": {
    "name": "Stein"
  },
  "types": "./types/index.d.ts",
  "userConfig": {
    "director": {
      "type": "string",
      "title": "Director",
      "description": "Who stages the scenes: hybrid (the model sets up each turn and wraps it up; everything in between is canned, so few tokens), full (the model stages every scene), or off (canned scenes only, no tokens).",
      "default": "hybrid",
      "options": [
        "hybrid",
        "full",
        "off"
      ]
    },
    "model": {
      "type": "string",
      "title": "Director model",
      "description": "Which model stages the scenes: sonnet (richer) or haiku (cheaper).",
      "default": "sonnet",
      "options": [
        "sonnet",
        "haiku"
      ]
    },
    "pace": {
      "type": "string",
      "title": "Pace",
      "description": "How busy Claude is: calm (long pauses), normal, or lively (quick and frequent scenes).",
      "default": "calm",
      "options": [
        "calm",
        "normal",
        "lively"
      ]
    },
    "showWhenIdle": {
      "type": "boolean",
      "title": "Show when idle",
      "description": "Keep the comic up between turns (Claude idles and dozes off). Off: only while Claude works.",
      "default": true
    }
  }
}

